const firebaseResponse = $input.first().json;
const userMessage = $('Edit Fields').item.json.message || '';
const wantsLast = /\b(últim|ultim)\b/i.test(userMessage);

if (firebaseResponse.error) {
  return [{ json: {
    message: userMessage,
    userId: $('Edit Fields').item.json.userId,
    userName: $('Edit Fields').item.json.userName,
    transactionsFormatted: '',
    transactionCount: 0,
    lastTransaction: '',
    wantsLast,
    wantsMonth: false,
    monthLabel: '',
    monthTransactionsFormatted: '',
    monthTotals: { receita: 0, despesa: 0, saldo: 0, count: 0 },
    monthSummary: `Não consegui acessar suas transações (erro: ${firebaseResponse.error.message || 'desconhecido'}).`
  }}];
}

const docs = firebaseResponse.documents || [];

const items = docs.map(doc => {
  const f = doc.fields || {};
  const ts = f.dataMovimentacao?.timestampValue;
  const dt = ts ? new Date(ts) : null;
  const dataPt = dt ? dt.toLocaleDateString('pt-BR') : 'Data não informada';
  const valorNum = parseFloat(f.valor?.doubleValue ?? f.valor?.integerValue ?? 0);
  const isSaida = f.isSaida?.booleanValue ?? false;
  const tipo = isSaida ? 'Despesa' : 'Receita';
  let nome = f.nome?.stringValue || 'Sem nome';
  const desc = f.descricao?.stringValue;
  if (desc && desc.trim() !== '') nome += ` (${desc})`;
  return { dt, data: dataPt, nome, valor: valorNum, tipo };
}).filter(i => i.dt !== null)
  .sort((a,b) => b.dt - a.dt);

const transactionsFormatted = items.map(i => {
  const valor = i.valor.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  const emoji = i.tipo === 'Despesa' ? '🔴' : '🟢';
  return `• [${i.data}] ${emoji} ${i.nome} - ${valor} (${i.tipo})`;
}).join('\n');

let lastTransaction = '';
if (items.length) {
  const i = items[0];
  const valor = i.valor.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  const emoji = i.tipo === 'Despesa' ? '🔴' : '🟢';
  lastTransaction = `[${i.data}] ${emoji} ${i.nome} - ${valor} (${i.tipo})`;
}

// Detecta mês/ano no texto (pt-BR)
const monthMap = {
  'janeiro': 0, 'fevereiro': 1, 'março': 2, 'marco': 2, 'abril': 3, 'maio': 4, 'junho': 5,
  'julho': 6, 'agosto': 7, 'setembro': 8, 'outubro': 9, 'novembro': 10, 'dezembro': 11
};
const lower = userMessage.toLowerCase();
let monthIdx = null;
for (const k of Object.keys(monthMap)) { if (lower.includes(k)) { monthIdx = monthMap[k]; break; } }

let year = null;
const yearMatch = lower.match(/\b(20\d{2})\b/);
if (yearMatch) { year = parseInt(yearMatch[1], 10); }
if (!year) { if (/(esse|deste|desse|este) ano/.test(lower)) { year = new Date().getFullYear(); } }

const wantsMonth = monthIdx !== null && (year !== null || /(esse|deste|desse|este) ano/.test(lower));
if (monthIdx !== null && year === null) { year = new Date().getFullYear(); }

let monthItems = [];
let monthTransactionsFormatted = '';
let monthTotals = { receita: 0, despesa: 0, saldo: 0, count: 0 };
let monthLabel = '';
let monthSummary = '';
if (wantsMonth) {
  monthItems = items.filter(i => i.dt.getMonth() === monthIdx && i.dt.getFullYear() === year);
  monthTransactionsFormatted = monthItems.map(i => {
    const valor = i.valor.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    const emoji = i.tipo === 'Despesa' ? '🔴' : '🟢';
    return `• [${i.data}] ${emoji} ${i.nome} - ${valor} (${i.tipo})`;
  }).join('\n');
  for (const m of monthItems) { if (m.tipo === 'Despesa') monthTotals.despesa += m.valor; else monthTotals.receita += m.valor; }
  monthTotals.saldo = monthTotals.receita - monthTotals.despesa;
  monthTotals.count = monthItems.length;
  const monthNames = ['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
  monthLabel = `${monthNames[monthIdx]}/${year}`;
  if (monthTotals.count > 0) {
    const r = monthTotals.receita.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    const d = monthTotals.despesa.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    const s = monthTotals.saldo.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    monthSummary = `Resumo de ${monthLabel}:\nTransações: ${monthTotals.count}\nReceitas: ${r}\nDespesas: ${d}\nSaldo: ${s}\n\n${monthTransactionsFormatted}`;
  } else {
    monthSummary = `Não encontrei transações para ${monthLabel}.`;
  }
}

return [{
  json: {
    message: userMessage,
    userId: $('Edit Fields').item.json.userId,
    userName: $('Edit Fields').item.json.userName,
    transactionsFormatted,
    transactionCount: items.length,
    lastTransaction,
    wantsLast,
    wantsMonth,
    monthLabel,
    monthTransactionsFormatted,
    monthTotals,
    monthSummary
  }
}];

